import{_ as e,o as n,c as r,a0 as a}from"./chunks/framework.BxrwG5q5.js";const y=JSON.parse('{"title":"Comparison with Competitors","description":"","frontmatter":{},"headers":[],"relativePath":"comparison/index.md","filePath":"comparison/index.md"}'),s={name:"comparison/index.md"};function d(i,t,o,l,g,c){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="comparison-with-competitors" tabindex="-1">Comparison with Competitors <a class="header-anchor" href="#comparison-with-competitors" aria-label="Permalink to &quot;Comparison with Competitors&quot;">​</a></h1><blockquote><p>See also: <a href="/config/guide/self-hosting.html">Self-Hosting Guide</a> · <a href="/config/guide/cost.html">Cost &amp; Scaling</a> · <a href="/config/features/segments.html">Segments</a></p></blockquote><p>How @jewel998/config stacks up against other feature flag platforms.</p><h2 id="feature-comparison" tabindex="-1">Feature Comparison <a class="header-anchor" href="#feature-comparison" aria-label="Permalink to &quot;Feature Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th style="text-align:center;">@jewel998/config</th><th style="text-align:center;">LaunchDarkly</th><th style="text-align:center;">ConfigCat</th><th style="text-align:center;">Flagsmith</th><th style="text-align:center;">Firebase Remote Config</th></tr></thead><tbody><tr><td><strong>Feature Flags</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><strong>Segments (reusable audiences)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Targeting Rules</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">⚠️ Basic conditions</td></tr><tr><td><strong>Percentage Rollouts</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><strong>Prerequisites (flag dependencies)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Scheduling</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Multi-Environment</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌ (separate projects)</td></tr><tr><td><strong>Audit Log</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Diff Viewer</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Webhooks</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Slack/Discord/Teams</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">⚠️ Slack only</td><td style="text-align:center;">⚠️ Slack only</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Custom Webhook Templates</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td></tr><tr><td><strong>RBAC (roles per project)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Server-Side Evaluation</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Auto-Context Detection</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td></tr><tr><td><strong>GDPR Tools (data deletion)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">⚠️</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Self-Hostable</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr><tr><td><strong>Open Source</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr><tr><td><strong>API Key Security (client/server)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">⚠️</td><td style="text-align:center;">⚠️</td><td style="text-align:center;">⚠️</td></tr></tbody></table><h2 id="pricing-comparison" tabindex="-1">Pricing Comparison <a class="header-anchor" href="#pricing-comparison" aria-label="Permalink to &quot;Pricing Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Free Tier</th><th>Paid Starting At</th><th>Per-Seat?</th></tr></thead><tbody><tr><td><strong>@jewel998/config</strong></td><td>Unlimited (self-hosted)</td><td>$0 forever</td><td>No</td></tr><tr><td>LaunchDarkly</td><td>None</td><td>~$500/mo</td><td>Yes</td></tr><tr><td>ConfigCat</td><td>10 flags, 2 environments</td><td>$100/mo</td><td>Yes</td></tr><tr><td>Flagsmith</td><td>50K requests</td><td>$45/mo</td><td>Yes</td></tr><tr><td>Firebase Remote Config</td><td>2000 parameters</td><td>Free</td><td>No</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Why not Firebase Remote Config?</p><p>Firebase Remote Config is free and performs server-side evaluation, but lacks reusable segments, detailed targeting rules with DNF conditions, a diff-based audit log, webhooks, environment isolation, team RBAC, and import/export tooling. It&#39;s a great starting point for simple use cases, but @jewel998/config provides the full feature flag management platform that growing teams need.</p></div><h2 id="what-we-solve-that-others-don-t" tabindex="-1">What We Solve That Others Don&#39;t <a class="header-anchor" href="#what-we-solve-that-others-don-t" aria-label="Permalink to &quot;What We Solve That Others Don&#39;t&quot;">​</a></h2><h3 id="_1-cost-barrier-for-startups" tabindex="-1">1. Cost Barrier for Startups <a class="header-anchor" href="#_1-cost-barrier-for-startups" aria-label="Permalink to &quot;1. Cost Barrier for Startups&quot;">​</a></h3><p>LaunchDarkly and ConfigCat price per seat and per environment. A 5-person team with dev/staging/prod can easily hit $500+/month just for feature flags. @jewel998/config runs on Firebase&#39;s free tier — $0/month regardless of team size.</p><h3 id="_2-data-ownership" tabindex="-1">2. Data Ownership <a class="header-anchor" href="#_2-data-ownership" aria-label="Permalink to &quot;2. Data Ownership&quot;">​</a></h3><p>With SaaS platforms, your feature flag data lives on their servers. You&#39;re subject to their uptime, their data policies, and their pricing changes. With @jewel998/config, everything runs on your own Firebase project. You control the data.</p><h3 id="_3-vendor-lock-in" tabindex="-1">3. Vendor Lock-in <a class="header-anchor" href="#_3-vendor-lock-in" aria-label="Permalink to &quot;3. Vendor Lock-in&quot;">​</a></h3><p>SaaS platforms use proprietary SDKs and APIs. Migrating away means rewriting integration code. @jewel998/config uses a standard, simple SDK with a transparent API — if you ever outgrow it, the data is in your Firestore.</p><h3 id="_4-complexity-of-self-hosting" tabindex="-1">4. Complexity of Self-Hosting <a class="header-anchor" href="#_4-complexity-of-self-hosting" aria-label="Permalink to &quot;4. Complexity of Self-Hosting&quot;">​</a></h3><p>Flagsmith is open-source but requires Docker, PostgreSQL, Redis, and significant ops effort. @jewel998/config deploys with a single <code>firebase deploy</code> — no servers to manage, no databases to maintain.</p><h3 id="_5-business-logic-exposure" tabindex="-1">5. Business Logic Exposure <a class="header-anchor" href="#_5-business-logic-exposure" aria-label="Permalink to &quot;5. Business Logic Exposure&quot;">​</a></h3><p>Most platforms send full targeting rules to the client SDK. @jewel998/config&#39;s client keys (<code>cid_</code>) enforce server-side evaluation — your targeting logic, segments, and rollout percentages are never exposed to the browser.</p><h2 id="when-to-choose-something-else" tabindex="-1">When to Choose Something Else <a class="header-anchor" href="#when-to-choose-something-else" aria-label="Permalink to &quot;When to Choose Something Else&quot;">​</a></h2><ul><li><strong>You need enterprise SSO/SAML</strong> — LaunchDarkly has this, we don&#39;t (yet)</li><li><strong>You need experimentation/A/B testing</strong> — LaunchDarkly and Split.io have built-in experimentation</li><li><strong>You need 99.99% SLA</strong> — SaaS platforms offer contractual uptime guarantees</li><li><strong>You have 100+ team members</strong> — Enterprise platforms have better governance features</li><li><strong>You need mobile-native SDKs</strong> — We currently support web/JS only</li></ul><p>For startups and small teams (1-20 people) that need real feature management without the enterprise price tag, @jewel998/config is the right choice.</p>',22)])])}const x=e(s,[["render",d]]);export{y as __pageData,x as default};
